SELECT 100 * (try_divide(sum(blocked_by_risk),sum(payment_intents))) AS risk_block_share_percent, sum(payment_intents) AS payment_intents, sum(blocked_by_risk) AS blocked_by_risk
FROM workspace.approval_copilot.gold_funnel_daily
WHERE country = 'BR' AND business_date = DATE'2026-06-18' AND blocked_by_risk IS NOT NULL AND payment_intents IS NOT NULL;
